// Stapel einer Etage bestätigen – Prüfung des Anfragekörpers. Jeder Bericht muss an seinen ENTWURF gebunden bleiben
// (anschließend vom Baustein « enregistrer » geprüft): Nichts anderes als diese Texte wird gespeichert.
const b = $input.first().json?.body ?? {};
const etage = Number(b.etage);
if (!Number.isInteger(etage) || etage < 0 || etage > 20) throw new Error('Ungültige Etage');
if (!Array.isArray(b.rapports) || b.rapports.length === 0 || b.rapports.length > 60) throw new Error('Berichte: 1 bis 60 erwartet');
// Der Name der bestätigenden Pflegekraft stammt aus ihrer SITZUNG (Token), nie aus dem Anfragekörper: Man kann nicht „im Namen von“ jemand anderem bestätigen.
const s = $('Sitzung').first().json.soignant;
return b.rapports.map((r) => ({ json: { brouillon_id: r?.brouillon_id, texte: r?.texte, valide_par: s.nom, soignant_id: s.identifiant, etage } }));

// Stapel einer Etage bestätigen – fasst die erfolgreichen Bestätigungen zusammen; die Ablehnungen (bereits bestätigt, nicht gefunden, leerer Text) werden aufgelistet.
const etage = $('Inhalt des Stapels').first().json.etage;
const sorties = $input.all().map((i) => i.json);
const valides = sorties.filter((s) => s.ok === true && s.action === 'generer_sbar');
const refuses = sorties
  .filter((s) => !(s.ok === true && s.action === 'generer_sbar'))
  .map((s) => ({ brouillon_id: s.brouillon_id ?? null, erreur: String(s.erreur ?? s.error?.message ?? s.error ?? 'Bestätigung abgelehnt').slice(0, 200) }));
return [{ json: { portee: 'etage', etage, validation_ids: valides.map((s) => s.validation_id), nb_valides: valides.length, refuses } }];

// Stapel einer Etage bestätigen – Antwort an die Oberfläche.
const l = $('Stapel zusammenführen').first().json;
const a = $input.first().json ?? {};
return [
  {
    json: {
      ok: l.nb_valides > 0,
      nb_valides: l.nb_valides,
      refuses: l.refuses,
      apres_validation: l.nb_valides === 0 ? null : a.error ? { erreur: String(a.error.message ?? a.error).slice(0, 200) } : { rag: a.rag, transmission: a.transmission },
    },
  },
];

// Stapel einer Etage bestätigen – Antwort an die Oberfläche.
const l = $('Stapel zusammenführen').first().json;
const a = $input.first().json ?? {};
return [
  {
    json: {
      ok: l.nb_valides > 0,
      nb_valides: l.nb_valides,
      refuses: l.refuses,
      apres_validation: l.nb_valides === 0 ? null : a.error ? { erreur: String(a.error.message ?? a.error).slice(0, 200) } : { rag: a.rag, transmission: a.transmission },
    },
  },
];

// Sitzungsprüfung – das « Bearer »-Token im Authorization-Header (43 URL-sichere Zeichen) wird gehasht (SHA-256): Nur der Hash steht in der Datenbank.
const entetes = $input.first().json?.headers ?? {};
const m = String(entetes.authorization ?? '').match(/^Bearer ([A-Za-z0-9_-]{43})$/);
if (!m) return [{ json: { hash: '' } }];
return [{ json: { hash: require('crypto').createHash('sha256').update(m[1]).digest('hex') } }];

// Sitzungsprüfung – Ergebnis: eine identifizierte Pflegekraft (Sitzung offen, nicht abgelaufen, Konto aktiv) oder nichts.
const r = $input.first().json ?? {};
if (!r.identifiant) return [{ json: { ok: false } }];
return [{ json: { ok: true, soignant: { identifiant: r.identifiant, nom: r.nom }, jeton_hash: r.jeton_hash } }];
